+-- Create job_events table to log all job state changes
+CREATE TABLE IF NOT EXISTS job_events (
+  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
+  job_id uuid NOT NULL REFERENCES jobs(id),
+  type text NOT NULL CHECK (type IN ('created', 'claimed')),
+  payload text NOT NULL,
+  created_at timestamptz NOT NULL DEFAULT NOW(),
+  processed_at timestamptz,
+  CONSTRAINT event_not_yet_processed CHECK (processed_at IS NULL OR processed_at >= created_at)
+);
+
+CREATE INDEX IF NOT EXISTS idx_job_events_processed ON job_events(processed_at, created_at);
+CREATE INDEX IF NOT EXISTS idx_job_events_created ON job_events(created_at);
