+import { createServer } from "http";
+import { getUnprocessedEvents, markEventProcessed } from "./events.ts";
+
+const PORT = process.env.PORT || 3000;
+
+export const startApi = (): void => {
+  const server = createServer(async (req, res) => {
+    res.setHeader("Content-Type", "application/json");
+
+    if (req.method === "GET" && req.url === "/api/job-events") {
+      const events = await getUnprocessedEvents();
+      res.writeHead(200);
+      res.end(JSON.stringify(events));
+      return;
+    }
+
+    if (req.method === "POST" && req.url?.startsWith("/api/job-events/")) {
+      const eventId = req.url.split("/").pop();
+      if (!eventId) {
+        res.writeHead(400);
+        res.end(JSON.stringify({ error: "Missing event ID" }));
+        return;
+      }
+
+      await markEventProcessed(eventId);
+      res.writeHead(200);
+      res.end(JSON.stringify({ ok: true }));
+      return;
+    }
+
+    res.writeHead(404);
+    res.end(JSON.stringify({ error: "Not found" }));
+  });
+
+  server.listen(PORT, () => {
+    console.log(`API server listening on port ${PORT}`);
+  });
+};
