+import { pool } from "./pool.ts";
+
+export interface JobEvent {
+  id: string;
+  job_id: string;
+  type: "created" | "claimed";
+  payload: string;
+  created_at: string;
+}
+
+export const publishEvent = async (
+  jobId: string,
+  type: "created" | "claimed",
+  payload: string,
+): Promise<void> => {
+  await pool.query(
+    "INSERT INTO job_events (job_id, type, payload) VALUES ($1, $2, $3)",
+    [jobId, type, payload],
+  );
+};
+
+export const getUnprocessedEvents = async (): Promise<JobEvent[]> => {
+  const result = await pool.query(
+    "SELECT id, job_id, type, payload, created_at FROM job_events WHERE processed_at IS NULL ORDER BY created_at LIMIT 100",
+  );
+  return result.rows;
+};
+
+export const markEventProcessed = async (eventId: string): Promise<void> => {
+  await pool.query(
+    "UPDATE job_events SET processed_at = NOW() WHERE id = $1",
+    [eventId],
+  );
+};
